using System;using System.IO;using System.Linq;using System.Text;using System.Security.Cryptography;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests
{
 public sealed class AdSaveTests
 {
  static string Raw(StateData d,int version){var c=new UnitySaveCodec();string p=c.Encode(d),hash;using(var h=SHA256.Create())hash=BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(p))).Replace("-","").ToLowerInvariant();return c.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=version,payload=p,sha256=hash});}
  [Test]public void V14OriginalMigratesPaidJobWithoutChangingWorkOrSharedNextId()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-ads-v14-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Game.New(1000000);s.Data=ScientificNumber.From(100000);s=Game.Research(s,"dataGeneration");var d=StateData.From(s);d.ads=null;d.researchJob.identityRecorded=false;d.researchJob.key=null;string raw=Raw(d,14),path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,new UnitySaveCodec());var load=store.Load(s.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.ResearchJob.identityRecorded,Is.True);Assert.That(load.State.ResearchJob.required,Is.EqualTo(s.ResearchJob.required));Assert.That(load.State.Workshop.nextId,Is.EqualTo(s.Workshop.nextId));long next=load.State.Workshop.nextId;var waiting=AdRewards.Begin(load.State,"research","persisted",0);store.Save(waiting);var reload=new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt);Assert.That(reload.Writable,Is.True,reload.Message);Assert.That(reload.State.Ads.pending.job,Is.EqualTo(load.State.ResearchJob.key));var cancelled=AdRewards.Complete(reload.State,"persisted","unavailable");Assert.That(cancelled.Ads.hasPending,Is.False);Assert.That(cancelled.Ads.counts,Is.All.Zero);Assert.That(cancelled.Workshop.nextId,Is.EqualTo(next));Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v14-original-*").Single()),Is.EqualTo(raw));}finally{Directory.Delete(dir,true);}}
  [Test]public void MissingCurrentAdOrJobMarkersLockOriginalInsteadOfRepairing()
  {string dir=Path.Combine(Path.GetTempPath(),"unity-ads-invalid-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"save.json");for(int mode=0;mode<4;mode++){var s=Game.New(1000000);s.Data=ScientificNumber.From(100000);s=Game.Research(s,"dataGeneration");var d=StateData.From(s);if(mode==0)d.ads=null;if(mode==1)d.researchJob.identityRecorded=false;if(mode==2)d.ads.counts[0]=6;if(mode==3){d.ads.hasPending=true;d.ads.pending=new CommerceRewardTicket{id="bad",kind="unknown",context="",job="",amount=ScientificNumber.One.ToData()};}string raw=Raw(d,15);File.WriteAllText(path,raw);Assert.That(new AtomicSaveStore(path,new UnitySaveCodec()).Load(s.SavedAt).Writable,Is.False,"bad "+mode);Assert.That(File.ReadAllText(path),Is.EqualTo(raw));}}finally{Directory.Delete(dir,true);}}
  [Test]public void LegacyRequestsSaveContextAndCancelWithoutQuotaOrBenefit()
  {var s=Game.New(1000000);s.Prestige.resets=1;s=AdRewards.BeginLegacy(s,"creditBoost","legacy-request");Assert.That(s.Ads.hasPending,Is.True);var codec=new UnitySaveCodec();s=codec.Decode(codec.Encode(StateData.From(s))).ToState();var failed=AdRewards.Complete(s,"legacy-request","unavailable");Assert.That(failed.Ads.hasPending,Is.False);Assert.That(failed.Ads.creditBoostUntil,Is.Zero);Assert.That(failed.Ads.legacyCounts,Is.All.Zero);s.Rewards.owned=new[]{"ai_singularity.pass.adfree"};var claimed=AdRewards.ClaimAdFree(s,"legacy-request");Assert.That(claimed.Ads.creditBoostUntil,Is.EqualTo(s.SavedAt+AdBalance.CreditBoostMs));Assert.That(claimed.Ads.legacyCounts[0],Is.EqualTo(1));Assert.That(AdRewards.ClaimAdFree(claimed,"legacy-request"),Is.SameAs(claimed));}
  [Test]public void AdFreeClaimsRequireActualEntitlementAndKeepOriginalLimitsAndDedupe()
  {var s=Game.New(1000000);s.Prestige.resets=1;s=AdRewards.Begin(s,"gems","no-right");s=AdRewards.ClaimAdFree(s,"no-right");Assert.That(s.Retention.gems,Is.EqualTo(Game.New(1000000).Retention.gems));s.Rewards.owned=new[]{"ai_singularity.pass.adfree"};s=AdRewards.Begin(s,"gems","right");s=AdRewards.ClaimAdFree(s,"right");Assert.That(s.Ads.counts[0],Is.EqualTo(1));Assert.That(AdRewards.ClaimAdFree(s,"right"),Is.SameAs(s));s=Market.BeginVideo(s,"market");s=Market.ClaimAdFree(s,"market");Assert.That(s.Market.adWindowUsed,Is.EqualTo(1));s=Capsules.BeginVideo(s,"capsule");s=Capsules.ClaimAdFree(s,"capsule");Assert.That(s.Capsules.videos,Is.EqualTo(1));Assert.That(s.Capsules.draws,Is.EqualTo(1));}
 }
}
